        change('n1-registry.h-1', '    const KernelRow* select(std::string_view op, const Geometry& g, int domain,\n                            SelectionTrace* why = nullptr, bool record = true,\n                            const RowFilter* accept = nullptr);', '    const KernelRow* select(std::string_view op, const Geometry& g, int domain,\n                            SelectionTrace* why = nullptr, bool record = true,\n                            const RowFilter* accept = nullptr, int rank = -1); /* BC_VTP14_N1_SELECT_RANK */'),
