        change('n1-registry.h-3', '    std::vector<Band> build_bands(std::string_view op, std::string_view ranged_key,\n                                  int64_t lo, int64_t hi, const Geometry& base,\n                                  const RowFilter* accept = nullptr);', '    std::vector<Band> build_bands(std::string_view op, std::string_view ranged_key,\n                                  int64_t lo, int64_t hi, const Geometry& base,\n                                  const RowFilter* accept = nullptr, int rank = -1);\n    /* BC_VTP14_N1_BANDS_RANK: rank argument is ignored by default legacy selection. */'),
        change('n1-registry.h-4', '    int code_device_ = 0;\n    bool no_device_code_ = false;', '    int code_device_ = 0;\n    /* BC_VTP14_N1_DEVICES_STORAGE: set at startup only, never mutated by rank threads. */\n    std::vector<int> code_devices_;\n    bool no_device_code_ = false;'),
